/* Lot 103: the reader paint with gamut-mapped colours and color-mix() in other spaces (generated by scripts/lot103_gen.py; expectations from scripts/lot103_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body id=b>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l103_sheet_0(void) {
    prep("body { color: red; background-color: color-mix(in srgb, currentColor 98.9%, hwb(720.905deg 0% 100% /0.44)) } #o { background-color: color-mix(in srgb, lightsteelblue, CURRENTCOLOR) } #i { color: CURRENTCOLOR }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#ff0000;background-color:#fe0000fd\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#d8626f\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    prep("body { color: red; background-color: rgb(62.7% 259 256) } #o { background: no-repeat color-mix(in srgb, #bba, currentcolor) } #i { background: url(x.png) red }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#ff0000;background-color:#a0ffff\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#ff0000;background-image:url(x.png)\"", style_of("i"));
    prep("body { color: color-mix(in hwb shorter hue, lch(none none 69.29) 49.1%, oklab(0.8344 -0.1027 -0.02) 23%) } #o { background-color: color-mix(in srgb, currentcolor, oklch(0.6916 0.0486 208.1)) } #i { background: url(x.png) color-mix(in rec2020, color(none display-p3 0.2056 0.235 0), 58% rgb(20 203 84 / 12.3%)) }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#234745b8\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#557d81dc\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    prep("body { color: color-mix(in srgb, color(prophoto-rgb 0.9823 0.6895 1), currentColor 50%); background: color-mix(in srgb, hwb(-0.5turn 0% 37% /0.5), currentcolor) } #o { background: url(x.png) red } #i { color: CURRENTCOLOR; background-color: red }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#805d7d\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#ff0000;background-image:url(x.png)\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#ff0000\"", style_of("i"));
    prep("body { background-color: CURRENTCOLOR } #o { color: color-mix(in srgb, CURRENTCOLOR 23%, #af8ded68); background: no-repeat currentcolor } #i { color: darkgreen }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#000000\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#6551898b;background-color:#6551898b;background-repeat:no-repeat\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#006400\"", style_of("i"));
    prep("body { color: lch(16.22 133.97 153.6); background-color: lch(59.63 69.65 7.77/85%) } #o { color: lab(5.85 62.44 -54.67); background: url(x.png) color-mix(in srgb, CURRENTCOLOR, color(prophoto-rgb 0.8884 0.83 0)) } #i { color: lch(82.22 47.98 71.8); background-color: color-mix(in srgb, lch(98.4 0.73 157.16), transparent) }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#001f06;background-color:#fa4c83d9\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#32004b\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#fac176;background-color:#f9fbfa80\"", style_of("i"));
}

